"""A tiny persistent key-value store backed by a single JSON document file.

Design (Approach A from SPEC.md): the whole store is one JSON object on disk
mapping keys to values. The object is loaded once when the store is opened and
kept in memory; every mutating operation rewrites the file in place so the
on-disk copy is always current. Reads are served from memory.
"""

from __future__ import annotations

import json
import os


class Store:
    """Persistent mapping of str -> str stored as a JSON object at ``path``."""

    def __init__(self, path: str):
        self._path = path
        self._closed = False
        self._data: dict[str, str] = self._load()

    # -- persistence -------------------------------------------------------

    def _load(self) -> dict[str, str]:
        """Read the JSON document at ``path``; create an empty one if missing."""
        try:
            with open(self._path, "r", encoding="utf-8") as f:
                raw = f.read()
        except FileNotFoundError:
            self._data = {}
            self._flush()
            return {}

        if not raw.strip():
            # Empty file (e.g. created by ``touch``): treat as an empty store.
            return {}

        data = json.loads(raw)
        if not isinstance(data, dict) or not all(
            isinstance(k, str) and isinstance(v, str) for k, v in data.items()
        ):
            raise ValueError(f"{self._path}: not a kvstore JSON object of str -> str")
        return data

    def _flush(self) -> None:
        """Rewrite the data file in place with the current in-memory contents.

        The file is written directly (no temp file) so that nothing but ``path``
        ever appears on disk, per the single-file constraint in SPEC.md.
        """
        with open(self._path, "w", encoding="utf-8") as f:
            json.dump(self._data, f, ensure_ascii=False, sort_keys=True, indent=2)
            f.write("\n")
            f.flush()
            os.fsync(f.fileno())

    def _check_open(self) -> None:
        if self._closed:
            raise ValueError("operation on closed Store")

    # -- public interface --------------------------------------------------

    def set(self, key: str, value: str) -> None:
        self._check_open()
        if not isinstance(key, str) or not isinstance(value, str):
            raise TypeError("keys and values must be str")
        self._data[key] = value
        self._flush()

    def get(self, key: str) -> str | None:
        self._check_open()
        return self._data.get(key)

    def delete(self, key: str) -> bool:
        self._check_open()
        if key not in self._data:
            return False
        del self._data[key]
        self._flush()
        return True

    def keys(self) -> list[str]:
        self._check_open()
        return sorted(self._data)

    def close(self) -> None:
        """Mark the store closed. All writes are already on disk."""
        self._closed = True

    # -- conveniences ------------------------------------------------------

    def __enter__(self) -> "Store":
        return self

    def __exit__(self, *exc) -> None:
        self.close()

    def __len__(self) -> int:
        return len(self._data)

    def __contains__(self, key: object) -> bool:
        return key in self._data

    def __repr__(self) -> str:
        state = "closed" if self._closed else "open"
        return f"Store({self._path!r}, {state}, {len(self._data)} keys)"
EOF
